<title>DeployCloud Blog — Discover the latest in web development</title>
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --bg:#FAFAFA;--bg-white:#FFFFFF;--text:#171717;--text-secondary:#555;--text-tertiary:#888;
  --accent:#0072F5;--accent-hover:#005FCC;--border:#E5E5E5;--border-light:#F0F0F0;
  --card-shadow:0 1px 3px rgba(0,0,0,.06),0 1px 2px rgba(0,0,0,.04);
  --card-shadow-hover:0 8px 25px rgba(0,0,0,.08),0 4px 10px rgba(0,0,0,.05);
  --radius:8px;--radius-lg:12px;--radius-pill:100px;
  --font:-apple-system,BlinkMacSystemFont,'Inter','Segoe UI',Roboto,Helvetica,Arial,sans-serif;
  --max-w:1200px;--header-h:64px;
}
html{scroll-behavior:smooth}
body{font-family:var(--font);color:var(--text);background:var(--bg);line-height:1.6;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
button{font-family:inherit;cursor:pointer;border:none;background:none}
img{display:block;max-width:100%}
.container{max-width:var(--max-w);margin:0 auto;padding:0 24px}

/* ═══ HEADER ═══ */
.header{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.85);backdrop-filter:blur(12px);border-bottom:1px solid var(--border)}
.header-inner{display:flex;align-items:center;height:var(--header-h);gap:8px}
.logo{font-size:18px;font-weight:700;letter-spacing:-.3px;white-space:nowrap;margin-right:24px}
.logo span{color:var(--accent)}
.nav-links{display:flex;align-items:center;gap:4px;flex:1}
.nav-link{padding:8px 12px;font-size:14px;font-weight:500;color:var(--text-secondary);border-radius:var(--radius);transition:color .15s,background .15s;position:relative;display:flex;align-items:center;gap:4px}
.nav-link:hover,.nav-link.active{color:var(--text);background:rgba(0,0,0,.04)}
.nav-link svg{width:12px;height:12px;opacity:.5;transition:transform .2s}
.nav-link.active svg{transform:rotate(180deg)}
.header-actions{display:flex;align-items:center;gap:8px;margin-left:auto;white-space:nowrap}
.btn-ghost{padding:8px 14px;font-size:14px;font-weight:500;color:var(--text-secondary);border-radius:var(--radius);transition:all .15s}
.btn-ghost:hover{color:var(--text);background:rgba(0,0,0,.04)}
.btn-ask-ai{display:flex;align-items:center;gap:6px;padding:7px 14px;font-size:13px;font-weight:500;color:var(--accent);border:1px solid var(--border);border-radius:var(--radius-pill);transition:all .15s}
.btn-ask-ai:hover{border-color:var(--accent);background:rgba(0,114,245,.04)}
.btn-primary{padding:8px 18px;font-size:14px;font-weight:600;color:#fff;background:var(--text);border-radius:var(--radius);transition:background .15s}
.btn-primary:hover{background:#333}

/* Mega Menu */
.mega-menu-overlay{position:fixed;inset:0;top:var(--header-h);z-index:90;background:rgba(0,0,0,.08);opacity:0;pointer-events:none;transition:opacity .2s}
.mega-menu-overlay.open{opacity:1;pointer-events:auto}
.mega-menu{position:absolute;top:var(--header-h);left:0;right:0;z-index:95;background:#fff;border-bottom:1px solid var(--border);box-shadow:0 12px 40px rgba(0,0,0,.08);transform:translateY(-8px);opacity:0;pointer-events:none;transition:transform .25s ease,opacity .2s}
.mega-menu.open{transform:translateY(0);opacity:1;pointer-events:auto}
.mega-menu-inner{max-width:var(--max-w);margin:0 auto;padding:32px 24px 36px;display:grid;grid-template-columns:repeat(3,1fr);gap:40px}
.mega-menu-col h3{font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.08em;color:var(--text-tertiary);margin-bottom:16px}
.mega-menu-item{display:block;padding:8px 0}
.mega-menu-item-title{font-size:14px;font-weight:600;color:var(--text);transition:color .15s}
.mega-menu-item-desc{font-size:13px;color:var(--text-tertiary);margin-top:2px}
.mega-menu-item:hover .mega-menu-item-title{color:var(--accent)}
.mega-menu-2col{grid-template-columns:repeat(2,1fr);gap:40px}

/* ═══ HERO / PAGE TITLE ═══ */
.page-hero{padding:56px 0 0;text-align:center}
.page-hero h1{font-size:clamp(32px,5vw,48px);font-weight:800;letter-spacing:-.03em;line-height:1.15;color:var(--text)}
.page-hero p{font-size:18px;color:var(--text-secondary);margin-top:12px;max-width:560px;margin-left:auto;margin-right:auto}

/* ═══ CATEGORY FILTERS ═══ */
.filters-bar{padding:32px 0 8px;position:sticky;top:var(--header-h);z-index:50;background:var(--bg)}
.filters-inner{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.pill-group{display:flex;align-items:center;gap:6px;flex-wrap:wrap;flex:1}
.pill{padding:7px 16px;font-size:13px;font-weight:500;color:var(--text-secondary);border:1px solid var(--border);border-radius:var(--radius-pill);transition:all .18s;white-space:nowrap}
.pill:hover{color:var(--text);border-color:#ccc;background:var(--bg-white)}
.pill.active{color:#fff;background:var(--text);border-color:var(--text)}
.search-box{position:relative;width:240px;flex-shrink:0}
.search-box input{width:100%;padding:8px 14px 8px 36px;font-size:13px;font-family:var(--font);border:1px solid var(--border);border-radius:var(--radius-pill);background:var(--bg-white);color:var(--text);outline:none;transition:border-color .15s,box-shadow .15s}
.search-box input:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(0,114,245,.1)}
.search-box input::placeholder{color:var(--text-tertiary)}
.search-icon{position:absolute;left:12px;top:50%;transform:translateY(-50%);width:16px;height:16px;color:var(--text-tertiary);pointer-events:none}

/* ═══ FEATURED ARTICLES ═══ */
.featured{padding:32px 0 48px}
.featured-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}
.featured-card{position:relative;border-radius:var(--radius-lg);overflow:hidden;background:var(--bg-white);border:1px solid var(--border);transition:box-shadow .25s,transform .25s;cursor:pointer}
.featured-card:hover{box-shadow:var(--card-shadow-hover);transform:translateY(-2px)}
.featured-card-body{padding:28px 28px 24px}
.featured-card .tag{display:inline-block;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.06em;color:var(--accent);margin-bottom:12px}
.featured-card h2{font-size:22px;font-weight:700;line-height:1.3;letter-spacing:-.02em;margin-bottom:10px}
.featured-card p{font-size:14px;color:var(--text-secondary);line-height:1.65;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.featured-card .meta{display:flex;align-items:center;gap:10px;margin-top:16px;font-size:13px;color:var(--text-tertiary)}
.featured-card .avatar{width:28px;height:28px;border-radius:50%;background:var(--accent);display:flex;align-items:center;justify-content:center;color:#fff;font-size:12px;font-weight:600;flex-shrink:0}
.featured-card.hero{grid-column:1;grid-row:1/3;display:flex;flex-direction:column}
.featured-card.hero .featured-card-body{flex:1;display:flex;flex-direction:column;padding:32px 32px 28px}
.featured-card.hero h2{font-size:28px}
.featured-card.hero p{-webkit-line-clamp:5;flex:1}

/* Stats bar inside hero featured card */
.stats-bar{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:20px;padding-top:20px;border-top:1px solid var(--border-light)}
.stat{text-align:center}
.stat-value{font-size:22px;font-weight:800;color:var(--accent);letter-spacing:-.02em}
.stat-label{font-size:11px;color:var(--text-tertiary);margin-top:2px;line-height:1.3}

/* ═══ LATEST NEWS ═══ */
.latest{padding:0 0 48px}
.latest-header{display:flex;align-items:baseline;justify-content:space-between;margin-bottom:24px}
.latest-header h2{font-size:24px;font-weight:700;letter-spacing:-.02em}
.post-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.post-card{background:var(--bg-white);border:1px solid var(--border);border-radius:var(--radius-lg);overflow:hidden;transition:box-shadow .25s,transform .25s;cursor:pointer;display:flex;flex-direction:column}
.post-card:hover{box-shadow:var(--card-shadow-hover);transform:translateY(-2px)}
.post-card-body{padding:24px 24px 20px;flex:1;display:flex;flex-direction:column}
.post-card .tag{display:inline-block;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.06em;color:var(--accent);margin-bottom:10px;align-self:flex-start}
.post-card h3{font-size:17px;font-weight:700;line-height:1.35;letter-spacing:-.01em;margin-bottom:8px}
.post-card .excerpt{font-size:14px;color:var(--text-secondary);line-height:1.6;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;flex:1}
.post-card .meta{display:flex;align-items:center;gap:10px;margin-top:14px;font-size:13px;color:var(--text-tertiary)}
.post-card .avatar{width:26px;height:26px;border-radius:50%;background:var(--accent);display:flex;align-items:center;justify-content:center;color:#fff;font-size:11px;font-weight:600;flex-shrink:0}
.show-more-wrap{text-align:center;padding:32px 0 0}
.btn-show-more{padding:12px 32px;font-size:14px;font-weight:600;color:var(--text);border:1px solid var(--border);border-radius:var(--radius-pill);transition:all .18s}
.btn-show-more:hover{border-color:#999;background:var(--bg-white);box-shadow:var(--card-shadow)}

/* No results */
.no-results{display:none;text-align:center;padding:64px 24px;color:var(--text-tertiary);font-size:15px;grid-column:1/-1}
.no-results.visible{display:block}
.no-results p:first-child{font-size:40px;margin-bottom:12px}

/* ═══ CTA BANNER ═══ */
.cta-section{padding:48px 0 56px}
.cta-card{background:var(--text);color:#fff;border-radius:var(--radius-lg);padding:56px 48px;text-align:center}
.cta-card h2{font-size:clamp(24px,3.5vw,36px);font-weight:800;letter-spacing:-.03em;line-height:1.2;margin-bottom:12px}
.cta-card h2 span{color:var(--accent)}
.cta-card p{font-size:16px;color:rgba(255,255,255,.65);margin-bottom:28px;max-width:500px;margin-left:auto;margin-right:auto}
.cta-buttons{display:flex;justify-content:center;gap:12px;flex-wrap:wrap}
.cta-btn-primary{padding:12px 28px;font-size:15px;font-weight:600;color:var(--text);background:#fff;border-radius:var(--radius);transition:all .18s}
.cta-btn-primary:hover{background:#e8e8e8}
.cta-btn-secondary{padding:12px 28px;font-size:15px;font-weight:600;color:rgba(255,255,255,.8);border:1px solid rgba(255,255,255,.2);border-radius:var(--radius);transition:all .18s}
.cta-btn-secondary:hover{color:#fff;border-color:rgba(255,255,255,.5);background:rgba(255,255,255,.06)}
.enterprise-strip{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-top:20px;background:var(--bg-white);border:1px solid var(--border);border-radius:var(--radius-lg);padding:24px 32px}
.enterprise-strip p{font-size:15px;color:var(--text-secondary);max-width:600px}
.enterprise-strip strong{color:var(--text);font-weight:600}
.btn-enterprise{padding:10px 24px;font-size:14px;font-weight:600;color:var(--accent);border:1px solid var(--accent);border-radius:var(--radius);white-space:nowrap;transition:all .18s}
.btn-enterprise:hover{background:rgba(0,114,245,.06)}

/* ═══ FOOTER ═══ */
.footer{background:var(--text);color:rgba(255,255,255,.55);padding:64px 0 32px}
.footer-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:32px 24px;margin-bottom:48px}
.footer-col h4{font-size:13px;font-weight:600;color:#fff;margin-bottom:14px;letter-spacing:.02em}
.footer-col a{display:block;font-size:13px;padding:3px 0;transition:color .15s}
.footer-col a:hover{color:#fff}
.footer-bottom{display:flex;align-items:center;justify-content:space-between;padding-top:24px;border-top:1px solid rgba(255,255,255,.1);font-size:13px;flex-wrap:wrap;gap:12px}
.footer-status{display:flex;align-items:center;gap:6px}
.status-dot{width:8px;height:8px;border-radius:50%;background:#22c55e}

/* ═══ RESPONSIVE ═══ */
@media(max-width:960px){
  .featured-grid{grid-template-columns:1fr}
  .featured-card.hero{grid-row:auto}
  .post-grid{grid-template-columns:repeat(2,1fr)}
  .mega-menu-inner{grid-template-columns:repeat(2,1fr);gap:24px}
  .footer-grid{grid-template-columns:repeat(3,1fr)}
  .enterprise-strip{flex-direction:column;text-align:center}
}
@media(max-width:640px){
  .post-grid{grid-template-columns:1fr}
  .filters-inner{flex-direction:column;align-items:stretch}
  .search-box{width:100%}
  .pill-group{overflow-x:auto;flex-wrap:nowrap;-webkit-overflow-scrolling:touch;padding-bottom:4px}
  .header-actions .btn-ghost,.header-actions .btn-ask-ai{display:none}
  .nav-links{display:none}
  .mobile-menu-btn{display:flex !important}
  .mega-menu-inner{grid-template-columns:1fr;gap:20px}
  .cta-card{padding:40px 24px}
  .footer-grid{grid-template-columns:repeat(2,1fr)}
  .stats-bar{grid-template-columns:1fr;gap:8px}
}
.mobile-menu-btn{display:none;align-items:center;justify-content:center;width:40px;height:40px;border-radius:var(--radius);margin-left:auto}
.mobile-menu-btn:hover{background:rgba(0,0,0,.05)}
.mobile-menu-btn svg{width:20px;height:20px}

/* Transitions for cards appearing */
.post-card{animation:fadeUp .35s ease both}
@keyframes fadeUp{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}
</style>
