const INITIAL_COUNT = 8;
const LOAD_MORE_COUNT = 6;
let visibleCount = INITIAL_COUNT;
let activeCategory = 'all';
let searchQuery = '';

const postGrid = document.getElementById('post-grid');
const noResults = document.getElementById('no-results');
const showMoreWrap = document.getElementById('show-more-wrap');
const btnShowMore = document.getElementById('btn-show-more');
const searchInput = document.getElementById('search-input');
const pillGroup = document.getElementById('pill-group');

function getFilteredPosts() {
  return allPosts.filter(post => {
    const matchCategory = activeCategory === 'all' || post.category === activeCategory;
    const matchSearch = !searchQuery ||
      post.title.toLowerCase().includes(searchQuery) ||
      post.excerpt.toLowerCase().includes(searchQuery) ||
      post.author.toLowerCase().includes(searchQuery) ||
      post.category.toLowerCase().includes(searchQuery);
    return matchCategory && matchSearch;
  });
}

function renderPosts() {
  const filtered = getFilteredPosts();
  const toShow = filtered.slice(0, visibleCount);

  if (toShow.length === 0) {
    postGrid.innerHTML = '';
    noResults.classList.add('visible');
    showMoreWrap.style.display = 'none';
    return;
  }

  noResults.classList.remove('visible');

  postGrid.innerHTML = toShow.map((post, i) => `
    <article class="post-card" style="animation-delay:${i * 0.04}s" data-category="${post.category}">
      <div class="post-card-body">
        <span class="tag">${post.category}</span>
        <h3>${post.title}</h3>
        <p class="excerpt">${post.excerpt}</p>
        <div class="meta">
          <div class="avatar">${post.initials}</div>
          <span>${post.author} &middot; ${post.date}</span>
        </div>
      </div>
    </article>
  `).join('');

  showMoreWrap.style.display = visibleCount < filtered.length ? '' : 'none';
}

// Category pills
pillGroup.addEventListener('click', e => {
  const pill = e.target.closest('.pill');
  if (!pill) return;
  pillGroup.querySelectorAll('.pill').forEach(p => p.classList.remove('active'));
  pill.classList.add('active');
  activeCategory = pill.dataset.category;
  visibleCount = INITIAL_COUNT;
  renderPosts();
});

// Search
searchInput.addEventListener('input', e => {
  searchQuery = e.target.value.toLowerCase().trim();
  visibleCount = INITIAL_COUNT;
  renderPosts();
});

// Show more
btnShowMore.addEventListener('click', () => {
  visibleCount += LOAD_MORE_COUNT;
  renderPosts();
});

// ═══ MEGA MENUS ═══
const dropdownBtns = document.querySelectorAll('[data-dropdown]');
const overlay = document.getElementById('mega-overlay');
let openMenu = null;

function closeMega() {
  if (openMenu) {
    document.getElementById('mega-' + openMenu).classList.remove('open');
    document.querySelector(`[data-dropdown="${openMenu}"]`).classList.remove('active');
    overlay.classList.remove('open');
    openMenu = null;
  }
}

function openMega(name) {
  if (openMenu === name) { closeMega(); return; }
  closeMega();
  openMenu = name;
  document.getElementById('mega-' + name).classList.add('open');
  document.querySelector(`[data-dropdown="${name}"]`).classList.add('active');
  overlay.classList.add('open');
}

dropdownBtns.forEach(btn => {
  btn.addEventListener('click', () => openMega(btn.dataset.dropdown));
});
overlay.addEventListener('click', closeMega);
document.addEventListener('keydown', e => { if (e.key === 'Escape') closeMega(); });

// Initial render
renderPosts();
